cat > tests/list-order.test.ts <<'EOF'
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { after, before, describe, it } from "node:test";
import vm from "node:vm";
import { openDatabase } from "../src/db.ts";
import { listTasks } from "../src/tasks.ts";
import { newDbPath, ROOT, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
}

async function fetchTasks(server: Running): Promise<{ tasks: Task[]; bytes: number }> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  const text = await response.text();
  return { tasks: (JSON.parse(text) as { tasks: Task[] }).tasks, bytes: Buffer.byteLength(text) };
}

describe("SL-008 open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added as A, B, C are listed C, B, A", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: GET /api/tasks returns C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        const response = await fetch(`${server.baseUrl}/api/tasks`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ title }),
        });
        assert.equal(response.status, 201);
        // distinct creation instants
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      const { tasks } = await fetchTasks(server);
      assert.deepEqual(
        tasks.map((t) => t.title),
        ["C", "B", "A"],
      );
    });
  });

  describe("AC-1: creation time decides the order, not the id", () => {
    it("AC-1: a task with a later created_at but a lower id is listed first", () => {
      const db = openDatabase(newDbPath());
      db.all(
        "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?), (?, ?, ?)",
        "later",
        "2026-01-02T00:00:00.000Z",
        "2026-01-02T00:00:00.000Z",
        "earlier",
        "2026-01-01T00:00:00.000Z",
        "2026-01-01T00:00:00.000Z",
      );
      assert.deepEqual(
        listTasks(db).map((t) => t.title),
        ["later", "earlier"],
      );
    });
  });

  describe("AC-2: tasks created at the same instant", () => {
    it("AC-2: the one saved last is listed first, every time", () => {
      const db = openDatabase(newDbPath());
      const instant = "2026-01-01T00:00:00.000Z";
      for (const title of ["first", "second", "third"]) {
        db.all(
          "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
          title,
          instant,
          instant,
        );
      }
      for (let run = 0; run < 20; run++) {
        assert.deepEqual(
          listTasks(db).map((t) => t.title),
          ["third", "second", "first"],
        );
      }
    });

    it("AC-2: tasks posted back to back come back in reverse order of saving", async () => {
      const server = await startServer();
      try {
        const titles = Array.from({ length: 30 }, (_, i) => `task ${i}`);
        for (const title of titles) {
          await fetch(`${server.baseUrl}/api/tasks`, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ title }),
          });
        }
        const { tasks } = await fetchTasks(server);
        assert.deepEqual(
          tasks.map((t) => t.title),
          [...titles].reverse(),
        );
      } finally {
        await server.stop();
      }
    });
  });

  describe("AC-3: an empty list shows an empty state and no error", () => {
    const html = readFileSync(`${ROOT}/public/index.html`, "utf8");
    const script = readFileSync(`${ROOT}/public/app.js`, "utf8");

    it("AC-3: the page has an empty-state element outside the task list", () => {
      assert.match(html, /<(\w+)[^>]+id=["']empty-state["'][^>]*>[^<]+<\/\1>/);
      const list = html.match(/<ul[^>]+id=["']task-list["'][^>]*>[\s\S]*?<\/ul>/)?.[0] ?? "";
      assert.doesNotMatch(list, /empty-state/);
    });

    /** Runs public/app.js against a fake DOM and a fake /api/tasks, then returns the elements. */
    async function runPage(tasks: { title: string }[]) {
      const element = (id: string) => ({
        id,
        hidden: false,
        textContent: "",
        value: "",
        children: [] as unknown[],
        addEventListener() {},
        replaceChildren(...nodes: unknown[]) {
          this.children = nodes;
        },
      });
      const elements: Record<string, ReturnType<typeof element>> = {
        "task-form": element("task-form"),
        "task-title": element("task-title"),
        "task-list": element("task-list"),
        "empty-state": element("empty-state"),
      };
      const context = {
        document: {
          getElementById: (id: string) => elements[id] ?? element(id),
          createElement: () => ({ textContent: "" }),
        },
        fetch: async () => ({ ok: true, status: 200, json: async () => ({ tasks }) }),
      };
      vm.runInNewContext(script, context);
      await new Promise((resolve) => setImmediate(resolve));
      return elements;
    }

    it("AC-3: with no tasks the empty state is visible and the list has no items", async () => {
      const page = await runPage([]);
      assert.equal(page["empty-state"].hidden, false);
      assert.equal(page["task-list"].children.length, 0);
    });

    it("AC-3: with tasks the empty state is hidden", async () => {
      const page = await runPage([{ title: "A" }]);
      assert.equal(page["empty-state"].hidden, true);
      assert.equal(page["task-list"].children.length, 1);
    });

    it("AC-3: GET /api/tasks on an empty database answers 200 with no tasks", async () => {
      const server = await startServer();
      try {
        const { tasks } = await fetchTasks(server);
        assert.deepEqual(tasks, []);
      } finally {
        await server.stop();
      }
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    let server: Running;
    before(async () => {
      const path = newDbPath();
      const db = openDatabase(path);
      db.all(
        `WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 1000)
         INSERT INTO tasks (title, created_at, updated_at)
         SELECT 'Task number ' || i || ' ' || printf('%.*c', 60, 'x'),
                strftime('%Y-%m-%dT%H:%M:%fZ', '2026-01-01', '+' || i || ' seconds'),
                strftime('%Y-%m-%dT%H:%M:%fZ', '2026-01-01', '+' || i || ' seconds')
         FROM n`,
      );
      server = await startServer(path);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: 20 sequential requests have p95 under 100 ms and a body under 400000 bytes", async () => {
      const durations: number[] = [];
      let last = { tasks: [] as Task[], bytes: 0 };
      for (let i = 0; i < 20; i++) {
        const start = performance.now();
        last = await fetchTasks(server);
        durations.push(performance.now() - start);
      }
      durations.sort((a, b) => a - b);
      const p95 = durations[Math.ceil(0.95 * durations.length) - 1];
      assert.equal(last.tasks.length, 1000);
      assert.equal(last.tasks[0].title.startsWith("Task number 1000 "), true);
      assert.ok(last.bytes < 400_000, `body was ${last.bytes} bytes`);
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
    });
  });
});
